// Reads one full Gmail message and decides what happens to it. Pure logic: no network calls.
// FILE   = genuine SIMBA email, account recognised, PDF link found -> filed in that account's folder.
// REVIEW = looks like a SIMBA invoice but something is unproven -> review folder for a person.
// IGNORE = not a SIMBA invoice email (for example an internal reply that does not quote one).
// The amount on the invoice is never read or used.
const SIMBA_SENDER = 'bills@my.simba.sg';
const SIMBA_DOMAIN = 'my.simba.sg';
const SES_DOMAIN = 'amazonses.com';
const GMAIL_AUTH_SERVER = 'mx.google.com';
const PDF_HOST = 'billing-invoice-pdf.amdocs-dbs.com';
const TRACKER_HOST_SUFFIX = '.awstrack.me';
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };

const settings = $('Intake Settings').first().json;
const message = $input.first().json;

function configured(value) {
  return typeof value === 'string' && value.trim() !== '' && !value.startsWith('REPLACE_WITH_');
}
for (const key of ['broadband_folder_id', 'mobile_folder_id', 'review_folder_id']) {
  if (!configured(settings[key])) {
    throw new Error('SIMBA intake settings are incomplete: set ' + key + ' in the Intake Settings node before activating.');
  }
}
if (settings.review_folder_id === settings.broadband_folder_id || settings.review_folder_id === settings.mobile_folder_id) {
  throw new Error('SIMBA intake settings: review_folder_id must be a different folder from the invoice folders, so review notes never land among filed invoices.');
}
// billing_addresses: the addresses SIMBA sends each account's bills to, as "address = SERVICE" pairs
// separated by new lines, commas or semicolons, e.g. "a@example.com = BROADBAND; b@example.com = MOBILE".
// Moving an account to a new billing address is an edit here only. Left as the placeholder, nothing matches.
const BILLING = new Map();
if (configured(settings.billing_addresses)) {
  for (const entry of settings.billing_addresses.split(/[\n,;]+/).map((s) => s.trim()).filter(Boolean)) {
    const pair = entry.match(/^([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})\s*=\s*(BROADBAND|MOBILE)$/i);
    if (!pair) {
      throw new Error('SIMBA intake settings: billing_addresses entry "' + entry.slice(0, 80) + '" is not "address = BROADBAND" or "address = MOBILE".');
    }
    const address = pair[1].toLowerCase();
    const serviceName = pair[2].toUpperCase();
    if (BILLING.has(address) && BILLING.get(address) !== serviceName) {
      throw new Error('SIMBA intake settings: billing_addresses lists ' + address + ' for both accounts.');
    }
    BILLING.set(address, serviceName);
  }
}

if (!message || typeof message.id !== 'string' || !/^[0-9a-f]{6,32}$/i.test(message.id) || !message.payload) {
  throw new Error('Gmail did not return a readable message; the SIMBA intake stopped so the email is not lost silently.');
}

const headers = Array.isArray(message.payload.headers) ? message.payload.headers : [];
function headerValues(name) {
  const lower = name.toLowerCase();
  return headers.filter((h) => h && typeof h.name === 'string' && h.name.toLowerCase() === lower).map((h) => String(h.value || ''));
}
function addressesIn(text) {
  return (String(text || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).map((a) => a.toLowerCase());
}
function decodeBase64Url(data) {
  if (typeof data !== 'string' || data === '') return '';
  return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
}

// Collect the plain-text and HTML bodies, and note any attached files.
const plainParts = [];
const htmlParts = [];
const attachments = [];
(function walk(part, depth) {
  if (!part || depth > 12) return;
  const type = String(part.mimeType || '').toLowerCase();
  const filename = typeof part.filename === 'string' ? part.filename : '';
  if (filename !== '' || (part.body && part.body.attachmentId)) {
    attachments.push(type || 'unknown');
  } else if (type === 'text/plain') {
    plainParts.push(decodeBase64Url(part.body && part.body.data));
  } else if (type === 'text/html') {
    htmlParts.push(decodeBase64Url(part.body && part.body.data));
  }
  if (Array.isArray(part.parts)) part.parts.forEach((child) => walk(child, depth + 1));
})(message.payload, 0);

function decodeEntities(text) {
  return text
    .replace(/&nbsp;/gi, ' ').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/gi, '&');
}
function htmlToText(html) {
  return decodeEntities(html
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' '));
}
function normaliseSpaces(text) {
  return text.replace(/[   ]/g, ' ').replace(/\r\n?/g, '\n');
}

const htmlText = htmlParts.map(htmlToText).join('\n');
const bodyText = normaliseSpaces([plainParts.join('\n'), htmlText].join('\n'));
const textWithoutLinks = bodyText.replace(/https?:\/\/[^\s<>"']+/gi, ' ');

// Links: from HTML href attributes and from the plain text.
const rawLinks = new Set();
for (const html of htmlParts) {
  for (const m of html.matchAll(/href\s*=\s*("([^"]*)"|'([^']*)')/gi)) rawLinks.add(decodeEntities(m[2] !== undefined ? m[2] : m[3]).trim());
}
for (const m of bodyText.matchAll(/https?:\/\/[^\s<>"'\])]+/gi)) rawLinks.add(m[0]);

function directPdfLink(raw) {
  let url;
  try { url = new URL(raw); } catch (error) { return null; }
  if (url.protocol !== 'https:' || url.hostname.toLowerCase() !== PDF_HOST) return null;
  if (url.username || url.password || (url.port !== '' && url.port !== '443')) return null;
  if (!/\/pdf$/i.test(url.pathname)) return null;
  url.hash = '';
  return url.toString();
}
// SIMBA links go through Amazon SES click tracking. The real PDF address sits URL-encoded in the
// tracking path (/L0/<encoded address>/...). It is read from there; the tracker is never called.
function pdfLinkFrom(raw) {
  let url;
  try { url = new URL(raw); } catch (error) { return null; }
  if (url.protocol === 'https:' && url.hostname.toLowerCase().endsWith(TRACKER_HOST_SUFFIX)) {
    const match = url.pathname.match(/^\/L\d+\/([^/]+)\//);
    if (!match) return null;
    let inner;
    try { inner = decodeURIComponent(match[1]); } catch (error) { return null; }
    return directPdfLink(inner);
  }
  return directPdfLink(raw);
}
const pdfLinks = [...new Set([...rawLinks].map(pdfLinkFrom).filter(Boolean))];

const invoiceNumbers = [...new Set([...textWithoutLinks.matchAll(/(?:^|[^A-Za-z0-9])(S\d{10})(?![0-9])/g)].map((m) => m[1]))];

function isoDate(day, monthName, year) {
  const month = MONTHS[String(monthName).toLowerCase()];
  const d = Number(day);
  const y = Number(year);
  if (!month || y < 2000 || y > 2100) return null;
  const check = new Date(Date.UTC(y, month - 1, d));
  if (check.getUTCFullYear() !== y || check.getUTCMonth() !== month - 1 || check.getUTCDate() !== d) return null;
  return String(y) + '-' + String(month).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}
const issueDateMatches = [...textWithoutLinks.matchAll(/Issued\s+On\s*:\s*(\d{1,2})-([A-Za-z]{3})-(\d{4})/gi)];
const issueDates = [...new Set(issueDateMatches.map((m) => isoDate(m[1], m[2], m[3]) || 'INVALID'))];

// Sender trust: only Gmail's own top Authentication-Results header counts. Anything lower down could
// have been written by the sender. It must show SIMBA's domain passing (DMARC, or DKIM signed by
// SIMBA's domain) and delivery through Amazon SES.
function parseAuthResults(value) {
  const cleaned = String(value || '').replace(/\([^()]*\)/g, ' ');
  const parts = cleaned.split(';').map((s) => s.trim()).filter(Boolean);
  const server = (parts.shift() || '').split(/\s+/)[0].toLowerCase();
  const results = [];
  for (const part of parts) {
    const head = part.match(/^([a-z0-9_-]+)\s*=\s*([a-z]+)/i);
    if (!head) continue;
    const props = {};
    for (const p of part.matchAll(/([a-z]+\.[a-z0-9_-]+)\s*=\s*"?([^\s";]+)"?/gi)) props[p[1].toLowerCase()] = p[2].toLowerCase();
    results.push({ method: head[1].toLowerCase(), result: head[2].toLowerCase(), props });
  }
  return { server, results };
}
function domainOf(value) {
  const text = String(value || '').toLowerCase();
  return text.includes('@') ? text.slice(text.lastIndexOf('@') + 1) : text;
}
function sameOrSubdomain(domain, base) {
  return domain === base || domain.endsWith('.' + base);
}

const fromHeaders = headerValues('From');
const fromAddresses = fromHeaders.length === 1 ? addressesIn(fromHeaders[0]) : [];
const fromIsSimba = fromAddresses.length === 1 && fromAddresses[0] === SIMBA_SENDER;
const claimsSimba = fromHeaders.some((value) => addressesIn(value).includes(SIMBA_SENDER));
const topAuth = parseAuthResults(headerValues('Authentication-Results')[0]);
const passed = (method) => topAuth.results.filter((r) => r.method === method && r.result === 'pass');
// Exactly one DMARC result, and it must pass for SIMBA's domain; a failing result is never outvoted.
const dmarcResults = topAuth.results.filter((r) => r.method === 'dmarc');
const simbaDomainPassed = topAuth.server === GMAIL_AUTH_SERVER && dmarcResults.length === 1
  && dmarcResults[0].result === 'pass' && dmarcResults[0].props['header.from'] === SIMBA_DOMAIN;
const sentThroughSes = topAuth.server === GMAIL_AUTH_SERVER && (
  passed('dkim').some((r) => sameOrSubdomain(domainOf(r.props['header.d'] || r.props['header.i']), SES_DOMAIN)) ||
  passed('spf').some((r) => sameOrSubdomain(domainOf(r.props['smtp.mailfrom']), SES_DOMAIN)));

let kind;
if (fromIsSimba && simbaDomainPassed && sentThroughSes) kind = 'DIRECT_VERIFIED';
else if (claimsSimba) kind = 'DIRECT_UNVERIFIED';
else if (bodyText.toLowerCase().includes(SIMBA_SENDER)) kind = 'FORWARDED_COPY';
else kind = 'NOT_SIMBA';

function servicesMatching(addresses) {
  return [...new Set(addresses.filter((address) => BILLING.has(address)).map((address) => BILLING.get(address)))];
}

let service = null;
let serviceHint = null;
const reasons = [];
if (kind === 'DIRECT_VERIFIED') {
  // The account comes only from the To header, which SIMBA's DKIM signature normally covers. Delivered-To,
  // X-Original-To and Cc are not used: anyone resending a genuine SIMBA email to us can add those.
  const toHeaders = headerValues('To');
  if (toHeaders.length !== 1 || headerValues('Cc').length > 1) {
    reasons.push('RECIPIENT_HEADERS_UNCLEAR');
  } else {
    const matched = servicesMatching(addressesIn(toHeaders[0]));
    if (matched.length === 1) service = matched[0];
    else reasons.push(matched.length === 0 ? 'ACCOUNT_NOT_RECOGNISED' : 'ACCOUNT_AMBIGUOUS');
  }
} else if (kind === 'DIRECT_UNVERIFIED') {
  reasons.push('SENDER_NOT_VERIFIED');
} else if (kind === 'FORWARDED_COPY') {
  reasons.push('FORWARDED_COPY');
  // Hint only: the quoted original "To:" line of a manual forward. Never trusted for filing.
  const quotedTo = [...bodyText.matchAll(/^[>\s]*To:\s*(.+)$/gim)].flatMap((m) => addressesIn(m[1]));
  const hinted = servicesMatching(quotedTo);
  if (hinted.length === 1) serviceHint = hinted[0];
}

if (kind !== 'NOT_SIMBA') {
  if (invoiceNumbers.length === 0) reasons.push('NO_INVOICE_NUMBER');
  if (invoiceNumbers.length > 1) reasons.push('SEVERAL_INVOICE_NUMBERS');
  if (issueDates.length === 0) reasons.push('NO_ISSUE_DATE');
  if (issueDates.length > 1 || issueDates.includes('INVALID')) reasons.push('ISSUE_DATE_UNCLEAR');
  if (pdfLinks.length === 0) reasons.push('NO_PDF_LINK');
  if (pdfLinks.length > 1) reasons.push('SEVERAL_PDF_LINKS');
  if (attachments.length > 0) reasons.push('UNEXPECTED_ATTACHMENT');
}

const invoiceNumber = invoiceNumbers.length === 1 ? invoiceNumbers[0] : null;
const issueDate = issueDates.length === 1 && issueDates[0] !== 'INVALID' ? issueDates[0] : null;
const route = kind === 'NOT_SIMBA' ? 'IGNORE' : (kind === 'DIRECT_VERIFIED' && reasons.length === 0 ? 'FILE' : 'REVIEW');
const receivedAt = /^\d{1,15}$/.test(String(message.internalDate || ''))
  ? new Date(Number(message.internalDate)).toISOString() : null;

return [{
  json: {
    schema: 'simba.invoice_intake.decision.v1',
    route,
    kind,
    service,
    service_hint: serviceHint,
    review_reasons: reasons,
    invoice_number: invoiceNumber,
    issue_date: issueDate,
    pdf_url: pdfLinks.length === 1 && route !== 'IGNORE' ? pdfLinks[0] : '',
    intake_key: invoiceNumber || ('gmail-' + message.id.toLowerCase()),
    gmail_message_id: message.id,
    internet_message_id: (headerValues('Message-ID')[0] || '').trim().slice(0, 300),
    received_at: receivedAt,
  },
}];

// Drive is the duplicate ledger: every stored file carries the invoice number (or the Gmail id when
// there is no number) in its Drive properties. A filed invoice is never stored twice. A review copy is
// never stored twice either, but a later genuine SIMBA email for the same invoice is still filed.
const decision = $('Read And Classify Invoice Email').first().json;
const search = $input.first().json;
if (!search || search.statusCode !== 200 || !search.body || !Array.isArray(search.body.files)) {
  throw new Error('Google Drive duplicate check failed (HTTP ' + (search && search.statusCode) + '). Nothing was stored; check the Google Drive credential and the n8n execution.');
}
if (search.body.incompleteSearch === true || search.body.nextPageToken) {
  throw new Error('Google Drive duplicate check was incomplete. Nothing was stored, to avoid a duplicate; check the n8n execution.');
}
const existing = search.body.files.filter((file) => file && file.trashed !== true && file.properties
  && file.properties.simbaIntakeKey === decision.intake_key);
const alreadyFiled = existing.some((file) => file.properties.simbaStatus === 'FILED');
let store = true;
let skipReason = null;
if (decision.route === 'FILE' && alreadyFiled) {
  store = false;
  skipReason = 'ALREADY_FILED';
} else if (decision.route === 'REVIEW' && existing.length > 0) {
  store = false;
  skipReason = 'ALREADY_IN_DRIVE';
}
return [{ json: Object.assign({}, decision, { store, skip_reason: skipReason, existing_copies: existing.length }) }];

// The download must really be a PDF: it starts with %PDF-, is not empty and is not oversized.
// A login page or error page from the PDF host fails here and the invoice goes to review instead.
const MAX_BYTES = 20 * 1024 * 1024;
const item = $input.first();
const file = item.binary && item.binary.data;
let problem = null;
let size = 0;
if (!file) {
  problem = 'NO_FILE_RETURNED';
} else {
  const bytes = await this.helpers.getBinaryDataBuffer(0, 'data');
  size = bytes.length;
  if (size < 5 || bytes.subarray(0, 5).toString('latin1') !== '%PDF-') problem = 'NOT_A_PDF';
  else if (size > MAX_BYTES) problem = 'TOO_LARGE';
}
const sha256 = String(item.json.pdf_sha256 || '').toLowerCase();
if (!problem && !/^[0-9a-f]{64}$/.test(sha256)) problem = 'NO_CHECKSUM';
if (problem) return [{ json: { pdf_check: 'FAILED', pdf_problem: problem } }];
return [{ json: { pdf_check: 'OK', pdf_sha256: sha256, pdf_size: size }, binary: { data: file } }];

// Builds the one file to store. A filed invoice keeps its PDF. Anything needing review goes to the
// review folder: its PDF when one was downloaded, otherwise a short text note saying what to check.
// The note never copies the PDF link, the amount or the email body.
const settings = $('Intake Settings').first().json;
const decision = $('Decide Whether To Store').first().json;
const input = $input.first();
const REASON_TEXT = {
  ACCOUNT_NOT_RECOGNISED: 'The email was not sent to any billing address listed in Intake Settings, so the account is unknown.',
  ACCOUNT_AMBIGUOUS: 'The email was sent to both a broadband and a mobile billing address, so the account is unclear.',
  RECIPIENT_HEADERS_UNCLEAR: 'The email has no single To line, or more than one Cc line, so where SIMBA sent it is unclear.',
  SENDER_NOT_VERIFIED: 'The email says it is from SIMBA, but Gmail could not confirm it really came from SIMBA. It may be fake.',
  FORWARDED_COPY: 'This is a forwarded copy, not the original SIMBA email, so the sender cannot be checked.',
  NO_INVOICE_NUMBER: 'No SIMBA invoice number (S followed by 10 digits) was found.',
  SEVERAL_INVOICE_NUMBERS: 'More than one invoice number was found.',
  NO_ISSUE_DATE: 'No "Issued On" date was found.',
  ISSUE_DATE_UNCLEAR: 'The "Issued On" date is repeated with different values or is not a real date.',
  NO_PDF_LINK: 'No link to the invoice PDF was found.',
  SEVERAL_PDF_LINKS: 'More than one invoice PDF link was found.',
  UNEXPECTED_ATTACHMENT: 'The email has an attached file. SIMBA invoices normally have only a link.',
  PDF_NOT_AVAILABLE: 'The invoice PDF could not be downloaded, or the download was not a valid PDF. The link may need a SIMBA login or may have expired.',
};
const SERVICE_NAME = { BROADBAND: 'Broadband', MOBILE: 'Mobile' };
const MONTH = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const reasons = decision.review_reasons.slice();
let route = decision.route;
const pdf = input.json.pdf_check === 'OK' && input.binary && input.binary.data ? input.binary.data : null;
if (decision.pdf_url && !pdf) {
  reasons.push('PDF_NOT_AVAILABLE');
  route = 'REVIEW';
}
// A filing that fell back to review must not add a second review copy of the same invoice.
if (route === 'REVIEW' && decision.route === 'FILE' && decision.existing_copies > 0) {
  return [{ json: { store: false, skip_reason: 'REVIEW_COPY_EXISTS', route } }];
}
const period = decision.issue_date
  ? MONTH[Number(decision.issue_date.slice(5, 7)) - 1] + ' ' + decision.issue_date.slice(0, 4) : null;

let name;
let folderId;
if (route === 'FILE') {
  folderId = decision.service === 'BROADBAND' ? settings.broadband_folder_id : settings.mobile_folder_id;
  name = period + ' - SIMBA ' + SERVICE_NAME[decision.service] + ' Invoice ' + decision.invoice_number + '.pdf';
} else {
  folderId = settings.review_folder_id;
  const hint = decision.service_hint ? 'probably ' + SERVICE_NAME[decision.service_hint] + ' ' : '';
  name = 'Needs review - ' + (period ? period + ' - ' : '') + 'SIMBA ' + hint + 'Invoice '
    + (decision.invoice_number || 'without number') + (pdf ? '.pdf' : '.txt');
}

const properties = {
  simbaIntakeKey: decision.intake_key,
  simbaStatus: route === 'FILE' ? 'FILED' : 'REVIEW',
  simbaGmailId: decision.gmail_message_id,
};
if (decision.service) properties.simbaAccount = decision.service;
else if (decision.service_hint) properties.simbaAccount = 'HINT_' + decision.service_hint;
if (pdf) properties.simbaSha256 = input.json.pdf_sha256;

if (pdf) {
  return [{
    json: { store: true, route, upload: { name, folder_id: folderId, mime_type: 'application/pdf', size: input.json.pdf_size, sha256: input.json.pdf_sha256, properties } },
    binary: { file: pdf },
  }];
}

let accountLine = 'unknown';
if (decision.service) accountLine = SERVICE_NAME[decision.service] + ' (from the billing address)';
else if (decision.service_hint) accountLine = 'probably ' + SERVICE_NAME[decision.service_hint] + ' (from the original recipient of the forwarded copy; not verified)';
const lines = [
  'A SIMBA invoice email needs a person to check it.',
  '',
  'Why it was not filed automatically:',
  ...[...new Set(reasons)].map((code) => '- ' + (REASON_TEXT[code] || code)),
  '',
  'What was found:',
  '- Invoice number: ' + (decision.invoice_number || 'not found'),
  '- Issued on: ' + (decision.issue_date || 'not found'),
  '- Account: ' + accountLine,
  '- Invoice PDF link in the email: ' + (decision.pdf_url ? 'yes (not copied here)' : 'no'),
  '- Email received: ' + (decision.received_at || 'unknown'),
  '- Gmail message id: ' + decision.gmail_message_id,
  '- To find it in Gmail, search for: rfc822msgid:' + (decision.internet_message_id || 'unknown').replace(/^<|>$/g, ''),
  '',
  'What to do: open the email, check it is a genuine SIMBA invoice and which account it belongs to,',
  'save the invoice PDF in that account\'s folder, then delete this note.',
  '',
];
const text = lines.join('\n');
return [{
  json: { store: true, route: 'REVIEW', upload: { name, folder_id: folderId, mime_type: 'text/plain', size: Buffer.byteLength(text, 'utf8'), sha256: null, properties } },
  binary: { file: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/plain', fileName: name, fileExtension: 'txt' } },
}];

// Google Drive answered the upload request with a one-time upload address. Pair it with the file.
const prepared = $('Prepare Drive File').first();
const start = $input.first().json;
const headers = (start && start.headers) || {};
const location = headers.location || headers.Location;
if (!start || start.statusCode !== 200 || typeof location !== 'string' || !location.startsWith('https://www.googleapis.com/upload/drive/v3/files?')) {
  throw new Error('Google Drive did not open an upload (HTTP ' + (start && start.statusCode) + '). Nothing was stored; check the Google Drive credential and the folder settings.');
}
return [{ json: { upload_url: location, mime_type: prepared.json.upload.mime_type }, binary: { file: prepared.binary.file } }];

// Reads the stored file back from Drive and checks it is exactly what was meant to be stored.
// Any difference stops the run so it shows as failed in n8n instead of passing silently.
const prepared = $('Prepare Drive File').first().json;
const upload = prepared.upload;
const put = $('Upload File Bytes').first().json;
const stored = $input.first().json;
if (!put || (put.statusCode !== 200 && put.statusCode !== 201) || !put.body || typeof put.body.id !== 'string') {
  throw new Error('Google Drive did not confirm the upload (HTTP ' + (put && put.statusCode) + '). Check the SIMBA folders in Drive before re-running.');
}
const file = stored && stored.statusCode === 200 ? stored.body : null;
const problems = [];
if (!file) {
  problems.push('read-back failed');
} else {
  if (file.id !== put.body.id) problems.push('different file id');
  if (file.name !== upload.name) problems.push('name');
  if (!Array.isArray(file.parents) || !file.parents.includes(upload.folder_id)) problems.push('folder');
  if (String(file.size) !== String(upload.size)) problems.push('size');
  if (file.trashed === true) problems.push('trashed');
  if (upload.sha256 && String(file.sha256Checksum || '').toLowerCase() !== upload.sha256) problems.push('checksum');
  const props = file.properties || {};
  for (const [key, value] of Object.entries(upload.properties)) {
    if (props[key] !== value) problems.push('property ' + key);
  }
}
if (problems.length > 0) {
  throw new Error('The file stored in Google Drive does not match (' + problems.join(', ') + '). Check the SIMBA folders in Drive.');
}
return [{ json: { stored: true, route: prepared.route, drive_file_id: file.id, name: file.name } }];
